<?php
define('APP_INIT',true);require dirname(__DIR__).'/config/config.php';require ROOT_PATH.'/config/database.php';require APP_PATH.'/core/Database.php';if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$db=Database::getInstance();$root=realpath(STORAGE_PATH.'/calls');$deleted=0;if($root){$rows=$db->query("SELECT id,recording_path FROM call_records WHERE recording_status='stored' AND recording_expires_at IS NOT NULL AND recording_expires_at<=NOW()")->fetchAll();foreach($rows as$r){$path=realpath($root.DIRECTORY_SEPARATOR.ltrim(str_replace('\\','/',$r['recording_path']),'/'));if(!$path||!str_starts_with(strtolower($path),strtolower($root.DIRECTORY_SEPARATOR))||!is_file($path))continue;if(@unlink($path)){$db->prepare("UPDATE call_records SET recording_status='expired',recording_path=NULL WHERE id=:id")->execute([':id'=>$r['id']]);$deleted++;}}}echo json_encode(['deleted'=>$deleted]).PHP_EOL;
